"""
Ray-based replacement for worker_comms.Worker_Manager.

Public API matches the original (`get_n_workers`, `start_workers`,
`stop_workers`, `update_worker_deployments`, `send_receive_workers`,
`send_receive_messages_workers`, `send_receive_worker`,
`send_messages_workers`) so existing drivers can opt in by importing
Worker_Manager from this module instead of `worker_comms`.

Internally, each "worker" is a long-lived Ray actor
(path_distribution_computer_ray.Path_Distribution_Computer.remote(...)) that
owns its persistent Gurobi model. The pickled (cmd, data) tuples that the
drivers already build are forwarded verbatim to `actor.handle_msg.remote(...)`,
which unpacks and dispatches them on the actor side.
"""
import os
import pickle
import multiprocessing
import threading
import time

import ray
from ray.exceptions import RayActorError

# Worker-actor death. A Ray actor dies permanently when its node is lost (e.g.
# AWS reclaims the spot worker). Calls to a dead actor raise RayActorError
# (ActorDiedError / ActorUnavailableError both subclass it). Normal task
# exceptions are RayTaskError — NOT a subclass — so they propagate unchanged;
# we only recover from genuine actor death.
_ACTOR_DEATH_EXC = (RayActorError,)


def _read_sys_avail_mb():
	"""Read MemAvailable from /proc/meminfo (Linux only). Returns int MB
	or None when the file isn't readable (macOS, restricted containers).
	Used by the autoscale policy in Worker_Manager._maybe_autoscale.
	"""
	try:
		with open('/proc/meminfo', 'r') as f:
			for line in f:
				if line.startswith('MemAvailable:'):
					return int(line.split()[1]) // 1024
	except (FileNotFoundError, PermissionError):
		return None
	return None

from helpers import *
from constants import *


# ---------------------------------------------------------------------- #
# Ray initialisation. We try to attach to a cluster first (auto-discover or
# RAY_ADDRESS), then fall back to local-mode so single-machine runs work
# without any extra setup. Idempotent: safe to import multiple times.
# ---------------------------------------------------------------------- #
def _ensure_ray():
	if ray.is_initialized():
		return
	address = os.environ.get('RAY_ADDRESS')
	# include_dashboard=False: the dashboard pulls in pydantic v1 which is
	# broken on Python 3.14 and we don't need a web UI for batch LP solving.
	# Set RAY_DASHBOARD=1 to re-enable.
	want_dashboard = os.environ.get('RAY_DASHBOARD') == '1'
	init_kwargs = dict(
		ignore_reinit_error=True,
		log_to_driver=True,
		include_dashboard=want_dashboard,
	)
	# SCULPTOR_RAY_NUM_CPUS (2026-08-16, measured on the 96-core head):
	# without a cap, EVERY per-cell local ray instance maintains ~cores idle
	# python workers at ~42 MB private RSS each -- 31 concurrent cells held
	# 2,651 ray::IDLE procs = ~111 GB (65% of box RAM) doing nothing, while
	# each cell used exactly ONE actor. Cap num_cpus to the actors a cell
	# actually spawns (SCULPTOR_N_WORKERS + slack). Env-gated: unset keeps
	# stock behavior.
	_ncpu = os.environ.get('SCULPTOR_RAY_NUM_CPUS')
	if _ncpu:
		init_kwargs['num_cpus'] = int(_ncpu)
	if address:
		ray.init(address=address, **init_kwargs)
		return
	try:
		# 'auto' attaches to a running cluster on this host if one exists.
		ray.init(address='auto', **init_kwargs)
		return
	except Exception:
		# No cluster -> local-mode. Uses all cores on this machine.
		ray.init(**init_kwargs)


_ensure_ray()

# Import after Ray is initialised so the @ray.remote decorator binds cleanly.
from experiments.solver_fork.path_distribution_computer_ray import Path_Distribution_Computer

# The actor class both construction sites below instantiate. A module-level
# seam so tooling (e.g. the ablation harness) can substitute a subclass;
# production behavior is unchanged (ACTOR_CLS is Path_Distribution_Computer).
ACTOR_CLS = Path_Distribution_Computer


class _ActorSocketShim:
	"""A tiny adapter so Ray actor handles look enough like a ZMQ REQ socket
	for `sparse_advertisements_v3.py` (and similar callers) that call
	`worker_socket.send(msg)` / `worker_socket.recv()` directly --
	bypassing the Worker_Manager API entirely.

	Public surface:
	  * .send(msg_bytes)       -- fires `actor.handle_msg.remote(msg_bytes)`
								  and records the future for the next recv().
	  * .recv()                -- blocks on the most recent send()'s future
								  and returns the result, pickled (mimics the
								  zmq REQ/REP wire format the original
								  workers used to send back).
	  * .handle_msg            -- pass-through to the actor, so internal
								  Worker_Manager methods can still do
								  `socket.handle_msg.remote(msg)` unchanged.
	  * .actor                 -- the raw Ray ActorHandle, for `ray.kill`.

	The original ZMQ REQ sockets enforced strict send/recv alternation;
	the call sites in sparse_advertisements_v3 follow that pattern, so a
	single-slot queue is sufficient. We don't bother emulating timeouts."""

	def __init__(self, actor):
		self.actor = actor
		self._pending = None  # at most one outstanding remote call

	# --- ZMQ-style wire API (for direct callers) -------------------------- #
	def send(self, msg_bytes):
		# Fire and remember.
		self._pending = self.actor.handle_msg.remote(msg_bytes)

	def recv(self):
		if self._pending is None:
			# Nothing in flight; return a benign empty pickled value rather
			# than raising, since callers sometimes do speculative recv().
			return pickle.dumps(None)
		result = ray.get(self._pending)
		self._pending = None
		return pickle.dumps(result)

	# --- Ray-native API (for Worker_Manager internal use) ----------------- #
	@property
	def handle_msg(self):
		return self.actor.handle_msg

	def __getattr__(self, name):
		# Forward any other attribute access to the underlying actor handle so
		# things like `socket.ping.remote()` keep working.
		return getattr(self.actor, name)


class Worker_Manager:
	"""Drop-in replacement for worker_comms.Worker_Manager that uses Ray actors
	instead of ZMQ subprocesses.

	Compatibility notes:
	  * `self.worker_sockets` is preserved as a dict { worker_i -> actor_handle }.
	    A few call sites in sparse_advertisements_v3.py / optimal_adv_wrapper.py
	    iterate it directly; only the keys are needed there, which still works.
	  * The `send_*` methods accept the same pickled (cmd, data) byte messages.
	"""

	def __init__(self, kwa_settings, deployment):
		self.kwa_settings = kwa_settings
		self.deployment = deployment
		self.dpsize = self.deployment['dpsize']
		self.worker_sockets = {}          # worker_i -> Ray actor handle
		self.worker_to_deployments = {}
		# Adaptive-resize state. compare_different_solutions spawns a watcher
		# thread that calls request_add_workers when concurrent parallel
		# strategies finish; the actual resize happens at the next sparse
		# iter boundary via process_pending_resize (single-threaded, no
		# concurrent fanouts in flight). See SCULPTOR_N_WORKERS_DURING_PARALLEL.
		#
		# When SCULPTOR_AUTOSCALE_WORKERS=1, process_pending_resize also runs
		# a memory-pressure policy that may request_add_workers or
		# request_remove_workers based on /proc/meminfo MemAvailable
		# against SCULPTOR_MEM_HEADROOM_MB.
		self._resize_lock = threading.Lock()
		self._pending_add_workers = 0
		self._pending_remove_workers = 0
		self._last_autoscale_decision = None  # for telemetry / debugging

	def get_init_kwa(self):
		return self.kwa_settings

	def get_n_workers(self):
		# Once workers are running, return the actual count. Partitioning
		# code (split_deployment_by_ug, send_receive_messages_workers
		# preallocators in optimal_adv_wrapper) calls this; after a
		# request_add_workers ramp, callers should see the new size.
		if self.worker_sockets:
			return len(self.worker_sockets)
		return self._target_n_workers()

	def _target_n_workers(self):
		# Original get_n_workers logic — the configured target count from
		# env var / heuristic. Used at start_workers time (before
		# self.worker_sockets is populated) and as the ceiling for
		# the post-parallel ramp-up.
		#
		# Same heuristic as the original: min(cpu_count, suggested_for_dpsize).
		# Allow env var override to escape the multiprocessing.cpu_count() trap
		# when the driver runs on a small head node but workers are larger
		# (e.g. driver on m7g.4xlarge has cpu_count==16 but worker c7g.16xlarge
		# has 64; without override we under-utilize the worker by 4x).
		# RAM caveat: at ~2-3 GB per actor for actual-32, cap at 32 on a
		# 128 GB worker to leave headroom.
		env_override = os.environ.get('SCULPTOR_N_WORKERS')
		if env_override is not None:
			try:
				suggested_num_workers = get_n_workers(self.dpsize)
				n = min(int(env_override), suggested_num_workers)
				return n
			except ValueError:
				print("WARNING: SCULPTOR_N_WORKERS={!r} is not an int; falling back".format(env_override))
		cpu_count = multiprocessing.cpu_count()
		suggested_num_workers = get_n_workers(self.dpsize)
		return min(cpu_count, suggested_num_workers)

	# ------------------------------------------------------------------ #
	# Lifecycle
	# ------------------------------------------------------------------ #
	def start_workers(self, n_workers_override=None):
		"""Spawn the initial pool of Ray actors.

		`n_workers_override` lets evaluate_all_metrics start with a smaller
		pool than SCULPTOR_N_WORKERS during the
		concurrent-parallel-strategies window. The remaining slots are
		added later via request_add_workers -> process_pending_resize.
		"""
		self.worker_to_deployments = {}
		if n_workers_override is not None:
			n_workers = n_workers_override
			print("[adaptive-workers] start_workers using override n_workers={}"
				  " (target={})".format(n_workers, self._target_n_workers()), flush=True)
		else:
			n_workers = self._target_n_workers()
			env_override = os.environ.get('SCULPTOR_N_WORKERS')
			if env_override is not None:
				print("SCULPTOR_N_WORKERS override active: n_workers={}".format(n_workers))

		# Split the deployment into (shared static dict, per-UG slices) and
		# ray.put the static dict ONCE. The actor constructor then receives
		# the static dict via ObjectRef (auto-dereferenced by Ray's actor
		# protocol from one shared plasma entry) plus its tiny per-UG slice
		# — avoiding 34 MB × n_workers of redundant pickling at actual-32
		# scale (~95 sec → ~10 sec wall for 64 actors).
		static_dep, slices = split_deployment_by_ug_separated(
			self.deployment, n_chunks=n_workers)
		static_dep_ref = ray.put(static_dep)

		# Same trick for init_kwa (already shared across actors).
		init_kwa = self.get_init_kwa()
		init_kwa_ref = ray.put(init_kwa)
		# SCULPTOR_WORKER_INIT_STAGGER_SEC: lightweight offset between actor
		# constructs. Actors still init in PARALLEL via Ray (we don't wait
		# for each __init__ to finish), but their start times are offset so
		# the per-actor transient memory peak doesn't overlap perfectly across
		# all 32 actors. Default 0 preserves original simultaneous-construct.
		# Small values (1-3s) give most of the memory-smoothing benefit at
		# small wall-time cost (n_workers * stagger_sec added during init only).
		stagger_sec = float(os.environ.get('SCULPTOR_WORKER_INIT_STAGGER_SEC', '0') or 0)
		if stagger_sec > 0:
			print("[Ray] Worker init spawn-staggered: {}s offset between .remote() calls"
				  .format(stagger_sec), flush=True)

		for worker in range(n_workers):
			if len(slices[worker]['ugs']) == 0:
				continue
			assert len(slices[worker]['ugs']) >= 1
			# worker_to_deployments stores the *full* per-worker dict so any
			# driver-side code that reads it (e.g. update_worker_deployments)
			# sees the same shape as before the refactor.
			self.worker_to_deployments[worker] = {**static_dep, **slices[worker]}
			# Construct the actor. The Ray scheduler picks a node/CPU.
			# Each actor's __init__ (in path_distribution_computer_ray) merges
			# the static + slice and sets up its persistent Gurobi model.
			actor = ACTOR_CLS.remote(
				worker, slices[worker], init_kwa_ref, static_dep_ref)
			# Wrap in a ZMQ-shaped shim so external code that calls
			# socket.send(msg)/socket.recv() (e.g. sparse_advertisements_v3
			# stop_tracker/set_iter loops) works unchanged. Worker_Manager's
			# own methods still use `.handle_msg.remote(...)` via the shim's
			# pass-through `handle_msg` property.
			self.worker_sockets[worker] = _ActorSocketShim(actor)
			# Offset next .remote() call without blocking on this actor's init.
			# Actors keep initializing in parallel under Ray; only their start
			# times differ. ray.get on all ping refs (below) is the actual sync.
			if stagger_sec > 0 and worker + 1 < n_workers:
				time.sleep(stagger_sec)

		# Block until every actor has finished __init__ -- matches the
		# behaviour of the original which waited for an ACK before returning.
		# Calling any method forces __init__ to complete.
		ready_refs = [self.worker_sockets[w].ping.remote()
					  for w in self.worker_sockets]
		ray.get(ready_refs)

	# ------------------------------------------------------------------ #
	# Adaptive resize (request from any thread; apply on main thread only)
	# ------------------------------------------------------------------ #
	def request_add_workers(self, n_add):
		"""Thread-safe request to grow the actor pool by `n_add`. The
		actual spawn + re-partition happens at the next
		process_pending_resize() call (typically the next sparse iter
		boundary), so we never mutate worker_sockets while a fanout is
		mid-flight. Called from the watcher thread spawned in
		compare_different_solutions when concurrent parallel-strategy
		subprocesses finish; also from the autoscale policy in
		process_pending_resize.
		"""
		with self._resize_lock:
			self._pending_add_workers += int(n_add)
			print("[adaptive-workers] request_add_workers(+{}) (pending_add={}, current={})".format(
				n_add, self._pending_add_workers, len(self.worker_sockets)), flush=True)

	def request_remove_workers(self, n_remove):
		"""Thread-safe request to SHRINK the actor pool by `n_remove`.
		Symmetric to request_add_workers. Used by the autoscale policy
		when head free memory drops below SCULPTOR_MEM_HEADROOM_MB.

		Highest-indexed workers are removed first (their cached LP
		state is not warmer than the others -- the cache hit rate is
		roughly uniform across workers since the gradient probes
		fan out evenly).
		"""
		with self._resize_lock:
			self._pending_remove_workers += int(n_remove)
			print("[adaptive-workers] request_remove_workers(-{}) (pending_remove={}, current={})".format(
				n_remove, self._pending_remove_workers, len(self.worker_sockets)), flush=True)

	def process_pending_resize(self):
		"""Main-thread consumer. Sparse's training loop calls this at iter
		boundary. Consumes pending add/remove deltas AND (if autoscale
		is enabled) runs the memory-headroom policy. All worker pool
		mutations happen here; no other code path should mutate
		self.worker_sockets while training is live.

		Single-threaded by contract: only one fanout in flight at a
		time, and resize runs between iters so no fanouts are active.
		"""
		# Memory-pressure policy may add to the pending counters before
		# we consume them. Runs first so its decisions get applied this
		# iter rather than waiting one more.
		self._maybe_autoscale()

		with self._resize_lock:
			n_add = self._pending_add_workers
			n_remove = self._pending_remove_workers
			self._pending_add_workers = 0
			self._pending_remove_workers = 0

		# Net out add vs remove so opposing requests in the same iter cancel.
		net = n_add - n_remove
		if net > 0:
			try:
				self._do_add_workers(net)
			except Exception as e:
				import traceback
				traceback.print_exc()
				print("[adaptive-workers] _do_add_workers({}) FAILED: {}".format(net, e), flush=True)
		elif net < 0:
			try:
				self._do_remove_workers(-net)
			except Exception as e:
				import traceback
				traceback.print_exc()
				print("[adaptive-workers] _do_remove_workers({}) FAILED: {}".format(-net, e), flush=True)

	def _maybe_autoscale(self):
		"""Memory-headroom policy. No-op unless SCULPTOR_AUTOSCALE_WORKERS=1.

		Below SCULPTOR_MEM_HEADROOM_MB free -> request_remove_workers(1)
		Above 2 * headroom free, and current < target -> request_add_workers(1)
		Between -> no change.

		One delta per call (per iter) gives natural hysteresis. The
		consumer below clamps net change to >=1 worker remaining.
		"""
		if os.environ.get('SCULPTOR_AUTOSCALE_WORKERS', '0') != '1':
			return
		try:
			head_headroom_mb = int(os.environ.get('SCULPTOR_MEM_HEADROOM_MB', '8000'))
		except ValueError:
			head_headroom_mb = 8000
		try:
			worker_headroom_mb = int(os.environ.get('SCULPTOR_WORKER_NODE_HEADROOM_MB', '8000'))
		except ValueError:
			worker_headroom_mb = 8000
		try:
			min_workers = int(os.environ.get('SCULPTOR_MIN_WORKERS', '1'))
		except ValueError:
			min_workers = 1

		head_avail = _read_sys_avail_mb()
		if head_avail is None:
			if not getattr(self, '_autoscale_warned_no_proc', False):
				print("[autoscale] WARNING: SCULPTOR_AUTOSCALE_WORKERS=1 set, but "
					  "/proc/meminfo on the head is not readable. Autoscale DISABLED. "
					  "Verify you're on Linux and /proc is mounted.", flush=True)
				self._autoscale_warned_no_proc = True
			return

		# Worker-node probe -- the head and worker live on different boxes,
		# and with 64 actors at ~2 GB each we can OOM the worker node before
		# the head feels pressure. Probe one Ray actor for its node's
		# MemAvailable. Best-effort: if probe fails (no actors yet, network
		# flake), worker_avail stays None and we fall through to head-only.
		worker_avail = self._read_worker_node_avail_mb()
		worker_tight = (worker_avail is not None and worker_avail < worker_headroom_mb)
		worker_ok = (worker_avail is None or worker_avail >= 2 * worker_headroom_mb)

		current = len(self.worker_sockets)
		target = self._target_n_workers()

		# SHRINK if either side is tight.
		if (head_avail < head_headroom_mb or worker_tight) and current > min_workers:
			self.request_remove_workers(1)
			reason = 'head' if head_avail < head_headroom_mb else 'worker'
			decision = 'remove({})'.format(reason)
		# GROW only if both sides comfortable (or worker probe unavailable).
		elif head_avail >= 2 * head_headroom_mb and worker_ok and current < target:
			self.request_add_workers(1)
			decision = 'add'
		else:
			decision = 'hold'

		self._last_autoscale_decision = {
			'decision': decision,
			'head_avail_mb': head_avail, 'worker_avail_mb': worker_avail,
			'head_headroom_mb': head_headroom_mb, 'worker_headroom_mb': worker_headroom_mb,
			'current': current, 'target': target,
		}
		print("[autoscale] decision={} head_avail_mb={} worker_avail_mb={} "
			  "(head_hr={}, worker_hr={}) current={} target={}".format(
				decision, head_avail, worker_avail,
				head_headroom_mb, worker_headroom_mb, current, target), flush=True)

	def _read_worker_node_avail_mb(self):
		"""Probe any Ray actor for its node's /proc/meminfo MemAvailable.
		Returns int MB, or None if probe fails. Used by _maybe_autoscale
		to monitor worker-node memory pressure separately from the head.
		"""
		if not self.worker_sockets:
			return None
		any_sock = next(iter(self.worker_sockets.values()))
		actor = getattr(any_sock, 'actor', any_sock)
		try:
			msg = pickle.dumps(('get_node_mem_avail_mb', None))
			ref = actor.handle_msg.remote(msg)
			return ray.get(ref, timeout=5)
		except Exception:
			return None

	def _do_add_workers(self, n_add):
		"""Spawn `n_add` Ray actors, re-partition the deployment across the
		new total, send updated slices to all (existing + new) workers,
		and merge new actors into self.worker_sockets.

		Stale entries in existing workers' caches (left from their
		previous UG slice) are not explicitly cleared — they remain
		valid as cache entries, just unused under the new slice, and
		Calc_Cache's MAX_CACHE_SIZE LRU will eventually evict them.
		"""
		# Defensive: clamp n_add so we never overshoot the configured
		# target. The watcher thread armed in compare_different_solutions
		# computes `n_to_add = target - current_at_arm_time` and stores it
		# in a closure; if autoscale's own `_maybe_autoscale` grows the
		# pool in the interim, current_now > current_at_arm_time and the
		# watcher's request would push past target. This clamp makes the
		# add request idempotent w.r.t. concurrent grow decisions.
		n_existing = len(self.worker_sockets)
		target = self._target_n_workers()
		clamped_n_add = max(0, min(n_add, target - n_existing))
		if clamped_n_add < n_add:
			print("[adaptive-workers] clamping add: {} -> {} (target={}, current={})".format(
				n_add, clamped_n_add, target, n_existing), flush=True)
		if clamped_n_add <= 0:
			return
		n_add = clamped_n_add
		n_total = n_existing + n_add
		print("[adaptive-workers] growing pool: {} -> {} (+{})".format(
			n_existing, n_total, n_add), flush=True)
		t0 = time.time()

		# Re-shard the deployment for the NEW total. split_deployment_by_ug_separated
		# returns (static_dep, [slice for each chunk]). Stable mapping:
		# index i in slices corresponds to worker_i.
		static_dep, slices = split_deployment_by_ug_separated(
			self.deployment, n_chunks=n_total)
		static_dep_ref = ray.put(static_dep)
		init_kwa_ref = ray.put(self.get_init_kwa())

		# 1) Spawn the new actors with their slices. Same construct pattern
		#    as start_workers — they boot their Gurobi shell + init_all_vars
		#    in parallel.
		new_sockets = {}
		stagger_sec = float(os.environ.get('SCULPTOR_WORKER_INIT_STAGGER_SEC', '0') or 0)
		for i in range(n_existing, n_total):
			if len(slices[i]['ugs']) == 0:
				continue
			actor = ACTOR_CLS.remote(
				i, slices[i], init_kwa_ref, static_dep_ref)
			new_sockets[i] = _ActorSocketShim(actor)
			if stagger_sec > 0 and i + 1 < n_total:
				time.sleep(stagger_sec)

		# 2) Wait for new actors to finish __init__.
		if new_sockets:
			ready_refs = [s.ping.remote() for s in new_sockets.values()]
			ray.get(ready_refs)
		t_init = time.time() - t0

		# 3) Re-shard existing workers — they need their NEW slice (which
		#    is a smaller portion of UGs than before). update_deployment
		#    on each.
		reshard_refs = []
		for i in range(n_existing):
			if i not in self.worker_sockets:
				continue
			if len(slices[i]['ugs']) == 0:
				continue
			new_subdep = {**static_dep, **slices[i]}
			self.worker_to_deployments[i] = new_subdep
			msg = pickle.dumps(('update_deployment', (new_subdep, {})))
			reshard_refs.append(self.worker_sockets[i].handle_msg.remote(msg))
		if reshard_refs:
			ray.get(reshard_refs)
		t_reshard = time.time() - t0 - t_init

		# 4) Merge new actors into worker_sockets. No lock needed because
		#    this method is called only from the main thread between iter
		#    boundaries (no concurrent fanouts).
		for i, sock in new_sockets.items():
			self.worker_sockets[i] = sock
			self.worker_to_deployments[i] = {**static_dep, **slices[i]}

		print("[adaptive-workers] pool now {} workers; init={:.1f}s reshard={:.1f}s".format(
			len(self.worker_sockets), t_init, t_reshard), flush=True)

	def _do_remove_workers(self, n_remove):
		"""Remove the highest-indexed `n_remove` actors from the pool and
		re-shard the deployment across the smaller pool.

		Steps:
		  1) Pick the worker_i keys to drop (highest indices first).
		  2) Pull their [mem-worker] log via dump_mem_log RPC and echo to
		     stdout (so the records are preserved in the sweep log even
		     though the actor is about to die).
		  3) Re-shard the deployment for the new (smaller) total.
		  4) Send each remaining worker its new (larger) UG slice via
		     update_deployment.
		  5) ray.kill the removed actors. The kill is forcible -- any
		     in-flight method call on a removed actor will error, which
		     is why this must run between iters (no fanouts in flight).
		"""
		n_existing = len(self.worker_sockets)
		# Floor at 1 worker -- can't run training with zero.
		actual_remove = min(n_remove, max(0, n_existing - 1))
		if actual_remove <= 0:
			print("[adaptive-workers] _do_remove_workers({}) skipped (already at min)".format(
				n_remove), flush=True)
			return
		n_total = n_existing - actual_remove
		print("[adaptive-workers] shrinking pool: {} -> {} (-{})".format(
			n_existing, n_total, actual_remove), flush=True)
		t0 = time.time()

		# 1) Highest indices first, but skip any missing keys (defensive).
		all_keys = sorted(self.worker_sockets.keys())
		to_remove = all_keys[-actual_remove:]
		to_keep = all_keys[:-actual_remove]

		# 2) Collect mem logs from the workers we're about to kill so we
		#    don't lose their records.
		dump_msg = pickle.dumps(('dump_mem_log', None))
		for worker_i in to_remove:
			try:
				ref = self.worker_sockets[worker_i].handle_msg.remote(dump_msg)
				content = ray.get(ref)
				if content:
					print('--- worker {} mem log (removed) start ---'.format(worker_i), flush=True)
					print(content, end='' if content.endswith('\n') else '\n', flush=True)
					print('--- worker {} mem log (removed) end ---'.format(worker_i), flush=True)
			except Exception:
				pass

		# 3) Re-shard for the new smaller total. We use the SAME indexing
		#    scheme as start_workers / _do_add_workers (slice[i] -> worker_i)
		#    by re-running split_deployment_by_ug_separated with n_chunks=n_total
		#    and then assigning those slices to the kept worker_i values in
		#    sorted order.
		static_dep, slices = split_deployment_by_ug_separated(
			self.deployment, n_chunks=n_total)
		# Note: slices is a list of n_total dicts. We map slices[k] -> kept worker
		# `to_keep[k]`. After this, the kept workers' worker_to_deployments
		# entries no longer match their physical worker_i (which is fine --
		# downstream code keys off worker_i, not slice index).

		# 4) Send each kept worker its new slice.
		reshard_refs = []
		for k, kept_i in enumerate(to_keep):
			if k >= len(slices) or len(slices[k]['ugs']) == 0:
				continue
			new_subdep = {**static_dep, **slices[k]}
			self.worker_to_deployments[kept_i] = new_subdep
			msg = pickle.dumps(('update_deployment', (new_subdep, {})))
			reshard_refs.append(self.worker_sockets[kept_i].handle_msg.remote(msg))
		if reshard_refs:
			ray.get(reshard_refs)
		t_reshard = time.time() - t0

		# 5) ray.kill the removed actors and drop them from worker_sockets.
		for worker_i in to_remove:
			sock = self.worker_sockets.pop(worker_i, None)
			self.worker_to_deployments.pop(worker_i, None)
			if sock is None:
				continue
			actor = getattr(sock, 'actor', sock)
			try:
				ray.kill(actor)
			except Exception:
				pass

		print("[adaptive-workers] pool now {} workers; reshard+kill={:.1f}s".format(
			len(self.worker_sockets), time.time() - t0), flush=True)

	def update_worker_deployments(self, new_deployment):
		self.deployment = new_deployment
		self.worker_to_deployments = {}
		n_workers = self.get_n_workers()
		print("Splitting deployment into subdeployments...")
		subdeployments = split_deployment_by_ug(self.deployment, n_chunks=n_workers)
		print("Done splitting deployment into subdeployments.")

		print("Sending deployment update messages...")
		refs = []
		for worker in range(n_workers):
			if len(subdeployments[worker]['ugs']) == 0:
				continue
			assert len(subdeployments[worker]['ugs']) >= 1
			self.worker_to_deployments[worker] = subdeployments[worker]
			msg = pickle.dumps(('update_deployment', (subdeployments[worker], {})))
			refs.append(self.worker_sockets[worker].handle_msg.remote(msg))
		print("Waiting for deployment ACK messages...")
		ray.get(refs)

	def _collect_and_emit_worker_mem_logs(self):
		"""Pull each Ray actor's per-process mem log file and echo to stdout
		so the lines land in the driver sweep log. Necessary because Ray's
		log_to_driver forwarding is unreliable in this cluster setup (zero
		[mem-worker] lines reached the boost2532 sweep log despite hooks
		firing inside the actors). Best-effort: any worker that errors is
		skipped silently. Must run BEFORE ray.kill empties the actors.
		"""
		try:
			msg = pickle.dumps(('dump_mem_log', None))
			results = self.send_receive_workers(msg)
		except Exception as e:
			print('[worker_mem_collect] failed: {}'.format(e), flush=True)
			return
		for worker_i in sorted(results):
			content = results.get(worker_i) or ''
			if content:
				print('--- worker {} mem log start ---'.format(worker_i), flush=True)
				print(content, end='' if content.endswith('\n') else '\n', flush=True)
				print('--- worker {} mem log end ---'.format(worker_i), flush=True)

	def stop_workers(self):
		# Pull per-worker mem logs BEFORE killing the actors (ray.kill is
		# terminal; the actor's file content would be lost otherwise --
		# even though the file persists on the worker host's /tmp, we
		# don't have a separate path to retrieve it without going through
		# the actor RPC).
		try:
			self._collect_and_emit_worker_mem_logs()
		except Exception as e:
			print('[worker_mem_collect] outer error: {}'.format(e), flush=True)
		for worker, sock in list(self.worker_sockets.items()):
			# `sock` is an _ActorSocketShim wrapping the actor handle. ray.kill
			# wants the raw actor.
			actor = getattr(sock, 'actor', sock)
			try:
				ray.kill(actor)
			except Exception:
				pass
		self.worker_sockets = {}

	# ------------------------------------------------------------------ #
	# Fault tolerance: recover from worker-actor death (e.g. spot reclaim)
	# ------------------------------------------------------------------ #
	def _rebuild_worker_pool(self):
		"""A worker actor died (typically AWS reclaiming the spot worker
		node). Tear down any surviving handles and re-spawn a fresh pool so
		the caller can retry. Blocks until the cluster has enough CPUs for the
		target pool -- after a reclaim the autoscaler boots a replacement node,
		which takes ~30-120s. Raises RuntimeError if capacity never returns
		within SCULPTOR_RECOVER_NODE_TIMEOUT_S (default 900s).

		Re-spawn re-shards self.deployment (the pool's init deployment). Any
		per-run state pushed later via update_deployment is NOT replayed here;
		the retried operation re-applies it (update_deployment messages carry
		their own subdeployments, and the eval phase re-runs update_deployment
		before each strategy), so the retry is self-correcting for the call
		paths that reach this.
		"""
		print("[ray-recover] worker actor death detected; rebuilding pool", flush=True)
		for w, sock in list(self.worker_sockets.items()):
			try:
				ray.kill(sock.actor)
			except Exception:
				pass
		self.worker_sockets = {}
		target = self._target_n_workers()
		timeout_s = float(os.environ.get('SCULPTOR_RECOVER_NODE_TIMEOUT_S', '900'))
		deadline = time.time() + timeout_s
		while True:
			try:
				cpus = ray.cluster_resources().get('CPU', 0)
			except Exception:
				cpus = 0
			if cpus >= target:
				break
			if time.time() >= deadline:
				raise RuntimeError(
					"[ray-recover] cluster never regained {} CPUs within {:.0f}s "
					"(have {:.0f}); cannot rebuild worker pool".format(
						target, timeout_s, cpus))
			print("[ray-recover] waiting for cluster CPUs: have {:.0f}, need {} "
				  "(replacement node booting?)".format(cpus, target), flush=True)
			time.sleep(10)
		self.start_workers()
		print("[ray-recover] rebuilt pool with {} workers".format(
			len(self.worker_sockets)), flush=True)

	def _with_recovery(self, fn):
		"""Run fn(); on worker-actor death, rebuild the pool once and retry.
		A second failure propagates so the caller's error handling still runs
		-- now after a genuine recovery attempt, not a silent swallow. fn must
		re-read self.worker_sockets each call (pass a lambda), since recovery
		replaces every handle."""
		try:
			return fn()
		except _ACTOR_DEATH_EXC as e:
			print("[ray-recover] {}: {}".format(type(e).__name__, str(e)[:300]), flush=True)
			self._rebuild_worker_pool()
			return fn()

	# ------------------------------------------------------------------ #
	# Message-passing primitives
	# ------------------------------------------------------------------ #
	def _fanout(self, items):
		"""items: iterable of (worker_i, msg_bytes). Submit all in flight,
		then ray.get the results. Returns {worker_i: result}."""
		pending = []
		for worker_i, msg in items:
			if worker_i not in self.worker_sockets:
				continue
			pending.append((worker_i, self.worker_sockets[worker_i].handle_msg.remote(msg)))
		rets = {}
		for worker_i, ref in pending:
			rets[worker_i] = ray.get(ref)
		return rets

	def send_receive_workers(self, msg, L_TIMEOUT=100 * 60):
		# Same msg to every worker. Original returns dict {worker_i: result}.
		return self._with_recovery(
			lambda: self._fanout([(w, msg) for w in self.worker_sockets]))

	def send_receive_messages_workers(self, msgs, L_TIMEOUT=100 * 60, **kwargs):
		# msgs is a list indexed by worker_i (matches original semantics).
		n_workers = kwargs.get('n_workers', self.get_n_workers())
		assert len(msgs) == n_workers
		return self._with_recovery(
			lambda: self._fanout([(i, msgs[i]) for i in range(n_workers)
								  if i in self.worker_sockets]))

	def send_receive_worker(self, worker_i, msg):
		return self._with_recovery(
			lambda: ray.get(self.worker_sockets[worker_i].handle_msg.remote(msg)))

	def send_messages_workers(self, msgs):
		"""Send (possibly distinct) messages to workers. The original waits for
		ACKs but does not return the per-worker payloads -- we mirror that.

		`msgs` may be either a dict {worker_i: msg} (as built in
		optimal_adv_wrapper.update_parent_tracker_workers) or a list indexed by
		worker_i. We accept both."""
		if isinstance(msgs, dict):
			items = list(msgs.items())
		else:
			items = list(enumerate(msgs))
		def _do():
			refs = []
			for worker_i, msg in items:
				if worker_i not in self.worker_sockets:
					continue
				refs.append(self.worker_sockets[worker_i].handle_msg.remote(msg))
			# Block on completion. (The original's send_messages_workers also
			# tries to recv ACKs, just without using them.)
			ray.get(refs)
		self._with_recovery(_do)
